package com.example.edujurnal.controller;
import com.example.edujurnal.service.*;
import java.time.LocalDate;import java.util.*;
import org.springframework.stereotype.Controller;import org.springframework.security.core.Authentication;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller
public class SchoolMessageController {
 private final SchoolMessageService service;private final ScheduleAccessService access;
 public SchoolMessageController(SchoolMessageService service,ScheduleAccessService access){this.service=service;this.access=access;}
 @GetMapping("/messages") public String list(Authentication auth,@RequestParam(defaultValue="ANNOUNCEMENT") String kind,@RequestParam(defaultValue="0") int page,Model model){
  page=Math.max(0,Math.min(page,100000));var rows=service.list(auth,kind,page);model.addAttribute("rows",rows.stream().limit(20).toList());model.addAttribute("more",rows.size()>20);model.addAttribute("pageNumber",page);model.addAttribute("kind",kind);model.addAttribute("user",access.currentUser(auth));return "communications/list";
 }
 @GetMapping("/messages/new") public String form(Authentication auth,@RequestParam(defaultValue="ANNOUNCEMENT") String kind,@RequestParam(required=false) Long classId,Model model){model.addAttribute("subgroups",service.subgroups(auth));model.addAttribute("lessons",service.lessonChoices(auth,classId));model.addAttribute("classes",service.classes(auth));model.addAttribute("students",service.students(auth,classId));model.addAttribute("classId",classId);model.addAttribute("kind",kind);model.addAttribute("token",UUID.randomUUID().toString());model.addAttribute("user",access.currentUser(auth));return "communications/form";}
 @org.springframework.transaction.annotation.Transactional @PostMapping("/messages") public String create(Authentication auth,@RequestParam String kind,@RequestParam String title,@RequestParam String body,@RequestParam(required=false) List<Long> classIds,@RequestParam(required=false) Long subgroupId,@RequestParam(required=false) Long studentId,@RequestParam(required=false) Long lessonId,@RequestParam(required=false) LocalDate date,@RequestParam String token,@RequestParam(required=false) org.springframework.web.multipart.MultipartFile[] files){long id=service.create(auth,kind,title,body,classIds,subgroupId,studentId,lessonId,date,token);service.attachments(auth,id,files);return "redirect:/messages/"+id;}
 @GetMapping("/messages/{id}") public String detail(Authentication auth,@PathVariable long id,Model model){model.addAttribute("files",service.attachments(auth,id));model.addAttribute("message",service.get(auth,id));model.addAttribute("history",service.history(auth,id));model.addAttribute("user",access.currentUser(auth));return "communications/detail";}
 @PostMapping("/messages/{id}/correct") public String correct(Authentication auth,@PathVariable long id,@RequestParam long version,@RequestParam String body,@RequestParam String reason){service.correct(auth,id,version,body,reason);return "redirect:/messages/"+id;}
 @GetMapping("/inbox") public String inbox(){return "redirect:/notifications";}
 @GetMapping("/message-files/{id}") public org.springframework.http.ResponseEntity<byte[]> download(Authentication auth,@PathVariable long id){var f=service.download(auth,id);return org.springframework.http.ResponseEntity.ok().header("X-Content-Type-Options","nosniff").header("Content-Disposition",org.springframework.http.ContentDisposition.attachment().filename((String)f.get("name"),java.nio.charset.StandardCharsets.UTF_8).build().toString()).contentType(org.springframework.http.MediaType.APPLICATION_OCTET_STREAM).body((byte[])f.get("data"));}}